export class TimeoutWatcher {
  private timers = new Map<string, NodeJS.Timeout>();
  private extensions = new Map<string, number>();  // count

  start(workerId: string, timeoutMs: number, killFn: () => Promise<void>): void {
    const timer = setTimeout(async () => {
      const extCount = this.extensions.get(workerId) ?? 0;
      const config = loadConfig();
      if (config.timeout?.runtime_extension_enabled && extCount < 2) {
        // Check progress: heartbeat last update + git diff size
        const progressing = await this.checkProgress(workerId);
        if (progressing) {
          this.extend(workerId, Math.round(timeoutMs * 0.5), killFn);
          return;
        }
      }
      await killFn();
    }, timeoutMs);
    this.timers.set(workerId, timer);
  }

  extend(workerId: string, extraMs: number, killFn: () => Promise<void>): void {
    const old = this.timers.get(workerId);
    if (old) clearTimeout(old);
    this.extensions.set(workerId, (this.extensions.get(workerId) ?? 0) + 1);
    this.start(workerId, extraMs, killFn);
    writeEvent({ ..., channel: 'BRAIN→WORKER:TIMEOUT_EXTEND', payload: { workerId, extraMs }});
  }

  stop(workerId: string): void {
    const t = this.timers.get(workerId);
    if (t) { clearTimeout(t); this.timers.delete(workerId); }
  }

  private async checkProgress(workerId: string): Promise<boolean> {
    // Read .tasks/<workerId>.hb, check last update + git diff line count
    // Return true if heartbeat fresh (<60s) AND git diff > 30 lines
  }
}
```

